function open(page,fromPop=false){if(!fromPop)history.pushState({aamSocialPage:page},'');if(page!=='chat'&&window.aamChatPresenceTimer){clearInterval(window.aamChatPresenceTimer);window.aamChatPresenceTimer=null;}if(page!=='chat'&&window.aamChatRefreshTimer){clearInterval(window.aamChatRefreshTimer);window.aamChatRefreshTimer=null;window.aamActiveChatId=null;}if(page==='home')return home();if(page==='upload')return upload();if(page==='status')return statusPage();if(page==='chat')return chat();if(page==='profile')return profile();if(page==='tools')return toolsPage();if(page==='coins')return coinsPage();document.getElementById('aamSocialDock')?.remove();if(adminToken()&&typeof window.admin==='function')return window.admin();if(typeof window.profile==='function')return window.profile();}
