window.aamBindAdminHold=(button,onUnlock)=>{if(!button||button.dataset.aamHoldBound)return;button.dataset.aamHoldBound='1';let frame=0,start=0;const stop=()=>{if(frame)cancelAnimationFrame(frame);frame=0;button.classList.remove('is-holding');button.style.setProperty('--hold-progress','0');};const tick=()=>{const progress=Math.min(1,(performance.now()-start)/4000);button.style.setProperty('--hold-progress',String(progress));if(progress>=1){stop();button.classList.add('is-unlocked');setTimeout(()=>button.classList.remove('is-unlocked'),650);onUnlock?.();return;}frame=requestAnimationFrame(tick);};button.addEventListener('pointerdown',event=>{if(event.button!==undefined&&event.button!==0)return;event.preventDefault();start=performance.now();button.classList.add('is-holding');try{button.setPointerCapture(event.pointerId);}catch(_){}frame=requestAnimationFrame(tick);});['pointerup','pointercancel','pointerleave','lostpointercapture'].forEach(name=>button.addEventListener(name,stop));button.addEventListener('contextmenu',event=>event.preventDefault());};
const bindExistingAdminButtons=()=>document.querySelectorAll('.tiny-admin').forEach(button=>window.aamBindAdminHold?.(button,()=>window.adminLogin?.()));bindExistingAdminButtons();if(document.body)new MutationObserver(bindExistingAdminButtons).observe(document.body,{childList:true,subtree:true});
function observeFeedViews(){const nodes=document.querySelectorAll('.aam-feed-item[data-post-id]');if(!nodes.length||!('IntersectionObserver'in window))return;const seen=new Set();const observer=new IntersectionObserver(entries=>{for(const entry of entries){const video=entry.target.querySelector('video');if(entry.isIntersecting&&entry.intersectionRatio>=0.65){const id=entry.target.dataset.postId;if(id&&!seen.has(id)){seen.add(id);api('/.netlify/functions/social-feed','POST',{action:'mark_view',post_id:id}).catch(()=>{});}if(video)video.play().catch(()=>{});}else if(video)video.pause();}},{threshold:[0,.65,1]});nodes.forEach(node=>observer.observe(node));window.aamFeedObserver?.disconnect?.();window.aamFeedObserver=observer;}
